/**
 * detective-voice.ts — Stage-scoped guidance copy for the DetectiveAside component.
 *
 * Authored by Kiro (2026-10-31).
 *
 * This module is a pure data/logic layer with no React, DOM, randomness, solver,
 * case, suspect, answer, server, storage, or AI dependency. The selection depends
 * only on locale and stage.
 *
 * Attribution note: The inherited application (engine, Game.tsx, CSS, server routes)
 * is Codex work. The hypothesis board (hypothesis.ts, HypothesisBoard.tsx, related
 * specs) is prior Kiro CLI work. This module and DetectiveAside.tsx are new Kiro work.
 */

import type { Locale } from '@/lib/game/types';

// ---------------------------------------------------------------------------
// Stage type
// ---------------------------------------------------------------------------

/** The six investigative stages that the aside tracks. */
export type DetectiveStage =
  | 'casting'
  | 'awakening'
  | 'listening'
  | 'confronting'
  | 'deducing'
  | 'reveal';

// ---------------------------------------------------------------------------
// Copy record
// ---------------------------------------------------------------------------

/** A single stage's localized guidance lines. */
export type StageCopy = {
  /** Short instruction, ~1–2 sentences, ≤ 25 English words. */
  line: string;
};

/** Full bilingual copy for one stage. */
type BilingualStageCopy = {
  ko: StageCopy;
  en: StageCopy;
};

/**
 * All twelve stage lines (six stages × two locales).
 *
 * English: idiomatic, dry, warm domestic-detective humor.
 * Korean: natural localization — not a word-for-word translation.
 *
 * No line invents evidence, suspects a particular object, references guilt,
 * describes a motive, or reacts differently based on accusation outcome.
 * The three code-owned official statements remain the only logical evidence.
 */
const VOICE_COPY: Record<DetectiveStage, BilingualStageCopy> = {
  casting: {
    ko: {
      line: '사진 속 물건 셋을 골라 눈을 붙여 주세요. 탐정의 첫 번째 임무는 용의자 확보입니다.',
    },
    en: {
      line: 'Pick three objects and place their faces. Every good case starts with a proper suspect list.',
    },
  },
  awakening: {
    ko: {
      line: '방이 깨어나는 중입니다. 아직 아무것도 할 필요 없어요 — 지켜만 보세요.',
    },
    en: {
      line: "Give them a moment. Waking up is hard enough without being immediately questioned.",
    },
  },
  listening: {
    ko: {
      line: '세 물건의 공식 증언을 모두 들어 주세요. 증거는 이 세 마디뿐입니다.',
    },
    en: {
      line: 'Hear all three official statements. These are the only evidence — take notes if you like.',
    },
  },
  confronting: {
    ko: {
      line: '각 물건을 추궁해 반론을 들으세요. 공식 증언과 나란히 놓고 비교해 보세요.',
    },
    en: {
      line: 'Question each object and compare their objection to the official statement. Pin the gap.',
    },
  },
  deducing: {
    ko: {
      line: '맞지 않는 가설을 직접 지워 가며 좁혀 보세요. 수첩은 정답을 모릅니다 — 당신만 알죠.',
    },
    en: {
      line: "Cross out worlds that don't fit. The notebook has no idea who did it — that part's on you.",
    },
  },
  reveal: {
    ko: {
      line: '사건이 마무리됐습니다. 해설을 읽으면 세 증언이 어떻게 이어지는지 확인할 수 있어요.',
    },
    en: {
      line: "Case closed. Read the explanation to see how the three statements fit together.",
    },
  },
};

// ---------------------------------------------------------------------------
// Accessor
// ---------------------------------------------------------------------------

/**
 * Returns the localized guidance copy for the given stage and locale.
 *
 * Deterministic: the same (stage, locale) pair always yields the same copy.
 * No randomness, no external I/O.
 */
export function getDetectiveVoice(stage: DetectiveStage, locale: Locale): StageCopy {
  return VOICE_COPY[stage][locale];
}

'use client';

/**
 * DetectiveAside.tsx — Stage-contextual guidance panel for Kirock Homes.
 *
 * Authored by Kiro (2026-10-31).
 *
 * A compact, purely presentational aside that pairs the /art/kirolock-homes.png
 * mascot image with stage-scoped detective guidance. Receives stage and locale as
 * props; holds no state and makes no network requests.
 *
 * Class names (detective-aside, detective-aside-mascot, detective-aside-copy,
 * detective-aside-title, detective-aside-line) and the data-testid attribute are
 * defined here; styling is Codex's responsibility.
 *
 * The image filename /art/kirolock-homes.png is intentionally historical and does
 * not reflect the current "Kirock" brand spelling — it is not an error to fix.
 *
 * Attribution note: The inherited application (engine, Game.tsx, CSS, server routes,
 * CrossExamination.tsx) is Codex work. The hypothesis board module and component are
 * prior Kiro CLI work. This component and detective-voice.ts are new Kiro work.
 */

import { getDetectiveVoice, type DetectiveStage } from '@/lib/ui/detective-voice';
import type { Locale } from '@/lib/game/types';

// Re-export so consumers can import the stage type from this file if preferred.
export type { DetectiveStage };

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export type DetectiveAsideProps = {
  stage: DetectiveStage;
  locale: Locale;
};

// ---------------------------------------------------------------------------
// Heading constants
// ---------------------------------------------------------------------------

const HEADING: Record<Locale, string> = {
  en: "Kirock's notebook",
  ko: '킬록의 수첩',
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * DetectiveAside
 *
 * Renders a compact aside with:
 *   - The Kirock Homes mascot image (decorative, empty alt, aria-hidden)
 *   - A localized heading ("Kirock's notebook" / "킬록의 수첩")
 *   - A short stage guidance line
 *
 * No correct/incorrect, guilt, suspect identity, case data, statement content,
 * solver, or private-answer information is accepted or displayed.
 *
 * The `data-stage` attribute on the aside element helps browser verification
 * confirm the active stage without inspecting copy text.
 */
export default function DetectiveAside({ stage, locale }: DetectiveAsideProps) {
  const copy = getDetectiveVoice(stage, locale);
  const heading = HEADING[locale];

  return (
    <aside
      className="detective-aside"
      data-testid="detective-aside"
      data-stage={stage}
      aria-label={heading}
    >
      {/*
        Decorative mascot image.
        - alt="" marks it as decorative for screen readers.
        - aria-hidden="true" prevents the empty alt from creating a redundant
          focusable element in some AT implementations.
        - Explicit width/height prevent layout shift (CLS).
        - The filename kirolock-homes.png is historical; see file header note.
      */}
      <img
        className="detective-aside-mascot"
        src="/art/kirolock-homes.png"
        alt=""
        aria-hidden="true"
        width={80}
        height={80}
        decoding="async"
      />

      <div className="detective-aside-copy">
        {/*
          Heading identifies the aside's purpose.
          h3 is appropriate when this aside appears inside a section that
          already has an h2; Codex may adjust the heading level to match
          the document outline after integration.
        */}
        <h3 className="detective-aside-title">{heading}</h3>

        {/*
          Stage guidance line.
          Not a live region: the aside updates as the player moves between
          phases, but the change is driven by navigation rather than
          background activity, so aria-live would create unnecessary noise.
          Codex may add role="status" if integration reveals a need.
        */}
        <p className="detective-aside-line">{copy.line}</p>
      </div>
    </aside>
  );
}

